console.log("Typing rapidly into the input field...");

// Simulate rapid calls (like typing quickly)
debouncedSearch("a");
debouncedSearch("ap");
debouncedSearch("app");
debouncedSearch("appl");
debouncedSearch("apple");

// After a pause of 500ms, only the last call ("apple") will execute.

setTimeout(() => {
    console.log("\n--- Pausing for 1 second ---");
    debouncedSearch("applet"); // This will be the only call after the pause
}, 1000);
